head.script:
// DOM 조회 순서(받은 id → mf_ 접두사 → G_ 뒤 접두사 → 접두사 제거). 2026-11
scwin.__getDom = function(id) {
	var P = 'mf_', d = function(k) { return document.getElementById(k); }, dd = function(k) { return k.replace(/(mf_){2,}/g, P); };
	var r = d(id); if (r) return r;
	var s = dd(P + id); r = d(s); if (r) return r;
	var g = s.indexOf('G_');
	if (g >= 0) { s = dd(s.slice(0, g + 2) + P + s.slice(g + 2)); r = d(s); if (r) return r; s = dd(P + s); r = d(s); if (r) return r; }
	return d(s.replace(P, ''));
};
// Jira 요건: setColumnIoFormat 의 calendarDisplayFormat 적용(col1=Jira 값)
gridView.setColumnIoFormat({
	colIndex : 0,
	ioFormat : "yyyyMMdd",
	calendarDisplayFormat : "yyyy-MM-dd"
});
// 기본 표시(yyyy-MM-dd)와 같아 col1 만으로는 반영 여부를 알 수 없음 → col2 에 다른 포맷 지정(그 외 조건 동일)
gridView.setColumnIoFormat({
	colIndex : 1,
	ioFormat : "yyyyMMdd",
	calendarDisplayFormat : "yyyy/MM/dd"
});
scwin.Dbclick = function(id) {
	var el = scwin.__getDom(id);
	scwin.fireDbClick(el);
};
scwin.fireDbClick = function(node) {
	if (document.createEventObject) {
		node.fireEvent('ondbclick');
	} else if (document.createEvent) {
		var evt = document.createEvent('MouseEvents');
		evt.initEvent('dblclick', true, false);
		node.dispatchEvent(evt);
	} else if (typeof node.ondbclick == 'function') {
		node.ondbclick();
	}
};
scwin.checkVal = function() {
	return (document.getElementById('G_gridView__col1_calendar_currentDate') || document.getElementById('mf_G_gridView__col1_calendar_currentDate') || document.getElementById('mf_G_mf_gridView__col1_calendar_currentDate') || document.getElementById('G_mf_gridView__col1_calendar_currentDate')).innerText == '2016-12-30';
};
